import React, { useEffect, useState } from "react";
import api from "../services/api";
import "./AutomationWidget.css";

const AutomationWidget = () => {
  const [automationLogs, setAutomationLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchAutomationLogs = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) return;

      const response = await api.get("/api/automation/fix_issue/", {
        headers: { Authorization: `Token ${token}` },
      });

      if (response.data.length > 0) {
        setAutomationLogs(response.data);
      }
      setLoading(false);
    } catch (error) {
      console.error("Error fetching automation logs:", error);
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAutomationLogs();
    const interval = setInterval(fetchAutomationLogs, 15000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="automation-widget">
      <h3>🔧 Automated Issue Resolution</h3>
      {loading ? <p>Loading...</p> : automationLogs.length > 0 ? (
        <ul>
          {automationLogs.map((log, idx) => (
            <li key={idx}>
              {log.timestamp}: {log.service_name} - {log.fix_result}
            </li>
          ))}
        </ul>
      ) : (
        <p>No automated fixes applied recently.</p>
      )}
    </div>
  );
};

export default AutomationWidget;
